1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import type { SendAttachment, SendPayload } from "@/lib/mail/types";
5	import { safeHtml } from "@/lib/mail/render";
6	import type { SignaturePlacement } from "@/lib/mail/signature";
7	import { Icon } from "./util";
8	
9	export type ComposeDraft = {
10	  mode: "new" | "reply" | "replyAll" | "forward";
11	  to: string;
12	  cc: string;
13	  subject: string;
14	  body: string; // plaintext the user edits
15	  quotedHtml?: string; // quoted original, appended below the reply
16	  signature?: string; // plain-text signature / fallback for the text part
17	  signatureHtml?: string; // sanitized rich-signature HTML for the HTML part
18	  signaturePlacement?: SignaturePlacement; // where the signature sits relative to quoted text
19	  inReplyToUid?: number;
20	  replyFolder?: string;
21	};
22	
23	// Attachment limits — mirrored server-side (the server re-validates and is the
24	// source of truth). Kept here only for fast, friendly client-side feedback.
25	const MAX_ATTACHMENTS = 10;
26	const MAX_ATTACHMENTS_TOTAL_BYTES = 20 * 1024 * 1024; // 20 MB
27	
28	// A file the user has attached, already read into base64 in the browser.
29	type Attachment = {
30	  id: string;
31	  filename: string;
32	  contentType: string;
33	  size: number; // decoded byte size
34	  contentBase64: string;
35	};
36	
37	function formatBytes(bytes: number): string {
38	  if (bytes < 1024) return `${bytes} B`;
39	  const kb = bytes / 1024;
40	  if (kb < 1024) return `${kb < 10 ? kb.toFixed(1) : Math.round(kb)} KB`;
41	  const mb = kb / 1024;
42	  return `${mb < 10 ? mb.toFixed(1) : Math.round(mb)} MB`;
43	}
44	
45	// Read a File into raw base64 (stripping the "data:*;base64," prefix).
46	function readFileBase64(file: File): Promise<string> {
47	  return new Promise((resolve, reject) => {
48	    const reader = new FileReader();
49	    reader.onerror = () => reject(new Error(`Could not read ${file.name}.`));
50	    reader.onload = () => {
51	      const result = String(reader.result || "");
52	      const comma = result.indexOf(",");
53	      resolve(comma >= 0 ? result.slice(comma + 1) : result);
54	    };
55	    reader.readAsDataURL(file);
56	  });
57	}
58	
59	export function Composer({
60	  draft,
61	  onClose,
62	  onSend,
63	}: {
64	  draft: ComposeDraft;
65	  onClose: () => void;
66	  onSend: (payload: SendPayload) => Promise<void>;
67	}) {
68	  const [to, setTo] = useState(draft.to);
69	  const [cc, setCc] = useState(draft.cc);
70	  const [showCc, setShowCc] = useState(!!draft.cc);
71	  const [subject, setSubject] = useState(draft.subject);
72	  const [body, setBody] = useState(draft.body);
73	  const [sending, setSending] = useState(false);
74	  const [error, setError] = useState<string | null>(null);
75	  const [attachments, setAttachments] = useState<Attachment[]>([]);
76	  const [reading, setReading] = useState(false);
77	  const [dragging, setDragging] = useState(false);
78	
79	  const fileInputRef = useRef<HTMLInputElement>(null);
80	  const dragDepth = useRef(0); // ignore nested dragenter/dragleave events
81	
82	  useEffect(() => {
83	    const onKey = (e: KeyboardEvent) => {
84	      if (e.key === "Escape" && !sending) onClose();
85	      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") void submit();
86	    };
87	    window.addEventListener("keydown", onKey);
88	    return () => window.removeEventListener("keydown", onKey);
89	    // eslint-disable-next-line react-hooks/exhaustive-deps
90	  }, [to, cc, subject, body, sending, attachments]);
91	
92	  const totalBytes = attachments.reduce((n, a) => n + a.size, 0);
93	
94	  // Read a batch of picked/dropped files, enforcing count + total-size caps.
95	  async function addFiles(files: FileList | File[]) {
96	    const list = Array.from(files);
97	    if (list.length === 0) return;
98	    setError(null);
99	
100	    let count = attachments.length;
101	    let running = totalBytes;
102	    const next: Attachment[] = [];
103	    setReading(true);
104	    try {
105	      for (const file of list) {
106	        if (count >= MAX_ATTACHMENTS) {
107	          setError(`You can attach up to ${MAX_ATTACHMENTS} files.`);
108	          break;
109	        }
110	        if (running + file.size > MAX_ATTACHMENTS_TOTAL_BYTES) {
111	          setError(`Attachments can total at most ${formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}.`);
112	          break;
113	        }
114	        try {
115	          const contentBase64 = await readFileBase64(file);
116	          next.push({
117	            id: `${Date.now()}-${count}-${Math.random().toString(36).slice(2, 8)}`,
118	            filename: file.name || "attachment",
119	            contentType: file.type || "application/octet-stream",
120	            size: file.size,
121	            contentBase64,
122	          });
123	          count += 1;
124	          running += file.size;
125	        } catch (e) {
126	          setError(e instanceof Error ? e.message : "Could not read a file.");
127	        }
128	      }
129	      if (next.length) setAttachments((prev) => [...prev, ...next]);
130	    } finally {
131	      setReading(false);
132	    }
133	  }
134	
135	  function removeAttachment(id: string) {
136	    setAttachments((prev) => prev.filter((a) => a.id !== id));
137	    if (error) setError(null);
138	  }
139	
140	  function onDrop(e: React.DragEvent) {
141	    e.preventDefault();
142	    dragDepth.current = 0;
143	    setDragging(false);
144	    if (e.dataTransfer?.files?.length) void addFiles(e.dataTransfer.files);
145	  }
146	
147	  const title =
148	    draft.mode === "new" ? "New message" : draft.mode === "forward" ? "Forward" : "Reply";
149	
150	  async function submit() {
151	    if (sending || reading) return;
152	    if (!to.trim()) {
153	      setError("Add at least one recipient.");
154	      return;
155	    }
156	    setError(null);
157	    setSending(true);
158	    try {
159	      const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
160	      // Compose the outgoing body. User text becomes the text part and, combined
161	      // with any quoted original + signature, the HTML part.
162	      const escaped = esc(body);
163	
164	      // Signature: prefer the sanitized rich-HTML signature; fall back to the
165	      // legacy plain-text one. `signatureHtml` is already sanitized server-side,
166	      // but we re-sanitize here as defence in depth.
167	      const sigPlain = draft.signature?.trim();
168	      const sigRichRaw = draft.signatureHtml?.trim();
169	      const sigRich = sigRichRaw ? safeHtml(sigRichRaw) : "";
170	      const sigText = sigPlain ? `\n\n-- \n${sigPlain}` : "";
171	      const sigHtml = sigRich
172	        ? `<br><br><div class="nx-sig">${sigRich}</div>`
173	        : sigPlain
174	          ? `<br><div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;line-height:1.6;color:#64748b">-- <br>${esc(sigPlain)}</div>`
175	          : "";
176	
177	      const userDiv = `<div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:14px;line-height:1.6;color:#1e293b">${escaped}</div>`;
178	      const quoteHtml = draft.quotedHtml
179	        ? `<br><blockquote style="margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b">${draft.quotedHtml}</blockquote>`
180	        : "";
181	
182	      // Placement only matters when there IS a quote (replies/forwards). "above"
183	      // puts the signature between the reply and the quoted original; "below"
184	      // (default) puts it after everything.
185	      const above = draft.signaturePlacement === "above";
186	      const htmlBody = above ? userDiv + sigHtml + quoteHtml : userDiv + quoteHtml + sigHtml;
187	
188	      const outAttachments: SendAttachment[] = attachments.map((a) => ({
189	        filename: a.filename,
190	        contentType: a.contentType,
191	        contentBase64: a.contentBase64,
192	      }));
193	
194	      await onSend({
195	        to: to.trim(),
196	        cc: cc.trim() || undefined,
197	        subject: subject.trim() || "(no subject)",
198	        text: body + sigText,
199	        html: htmlBody,
200	        attachments: outAttachments.length ? outAttachments : undefined,
201	        inReplyToUid: draft.inReplyToUid,
202	        replyFolder: draft.replyFolder,
203	      });
204	      onClose();
205	    } catch (e) {
206	      setError(e instanceof Error ? e.message : "Failed to send. Please try again.");
207	      setSending(false);
208	    }
209	  }
210	
211	  return (
212	    <div className="fixed inset-0 z-50 flex items-end justify-center bg-navy-950/70 p-0 backdrop-blur-sm sm:items-center sm:p-4" role="dialog" aria-modal="true" aria-label={title}>
213	      <div
214	        className="glass relative flex h-[85vh] w-full max-w-2xl flex-col overflow-hidden shadow-2xl animate-fade-up sm:h-auto sm:max-h-[85vh]"
215	        onClick={(e) => e.stopPropagation()}
216	        onDragEnter={(e) => {
217	          if (!e.dataTransfer?.types?.includes("Files")) return;
218	          e.preventDefault();
219	          dragDepth.current += 1;
220	          setDragging(true);
221	        }}
222	        onDragOver={(e) => {
223	          if (e.dataTransfer?.types?.includes("Files")) e.preventDefault();
224	        }}
225	        onDragLeave={() => {
226	          dragDepth.current = Math.max(0, dragDepth.current - 1);
227	          if (dragDepth.current === 0) setDragging(false);
228	        }}
229	        onDrop={onDrop}
230	      >
231	        {/* Drag-and-drop overlay */}
232	        {dragging && (
233	          <div className="pointer-events-none absolute inset-0 z-10 flex items-center justify-center bg-navy-950/80 backdrop-blur-sm">
234	            <div className="flex flex-col items-center gap-2 rounded-xl border-2 border-dashed border-brand-400/60 bg-white/[0.04] px-8 py-6 text-brand-200">
235	              <Icon.paperclip size={22} />
236	              <span className="text-sm font-medium">Drop files to attach</span>
237	            </div>
238	          </div>
239	        )}
240	
241	        {/* Header */}
242	        <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
243	          <h3 className="flex items-center gap-2 text-sm font-semibold text-white">
244	            <span className="text-brand-300"><Icon.compose size={16} /></span>
245	            {title}
246	          </h3>
247	          <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Close">
248	            <Icon.close size={16} />
249	          </button>
250	        </div>
251	
252	        {/* Fields */}
253	        <div className="flex-1 overflow-y-auto">
254	          <FieldRow label="To">
255	            <input
256	              autoFocus={draft.mode !== "reply" && draft.mode !== "replyAll"}
257	              value={to}
258	              onChange={(e) => setTo(e.target.value)}
259	              placeholder="name@example.com, another@example.com"
260	              className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
261	            />
262	            {!showCc && (
263	              <button onClick={() => setShowCc(true)} className="ml-2 flex-none text-xs font-medium text-slate-500 hover:text-brand-300">
264	                Cc
265	              </button>
266	            )}
267	          </FieldRow>
268	
269	          {showCc && (
270	            <FieldRow label="Cc">
271	              <input
272	                value={cc}
273	                onChange={(e) => setCc(e.target.value)}
274	                placeholder="cc@example.com"
275	                className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
276	              />
277	            </FieldRow>
278	          )}
279	
280	          <FieldRow label="Subject">
281	            <input
282	              value={subject}
283	              onChange={(e) => setSubject(e.target.value)}
284	              placeholder="Subject"
285	              className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
286	            />
287	          </FieldRow>
288	
289	          <textarea
290	            autoFocus={draft.mode === "reply" || draft.mode === "replyAll"}
291	            value={body}
292	            onChange={(e) => setBody(e.target.value)}
293	            placeholder="Write your message…"
294	            className="min-h-[16rem] w-full flex-1 resize-none bg-transparent px-5 py-4 text-sm leading-relaxed text-slate-100 outline-none placeholder:text-slate-600"
295	          />
296	
297	          {draft.quotedHtml && (
298	            <p className="px-5 pb-4 text-xs text-slate-600">
299	              — the original message is quoted below your reply —
300	            </p>
301	          )}
302	
303	          {/* Attachment chips */}
304	          {attachments.length > 0 && (
305	            <div className="border-t border-white/[0.06] px-5 py-3">
306	              <div className="mb-2 flex items-center justify-between text-[11px] text-slate-500">
307	                <span>
308	                  {attachments.length} {attachments.length === 1 ? "attachment" : "attachments"}
309	                </span>
310	                <span>{formatBytes(totalBytes)} / {formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}</span>
311	              </div>
312	              <div className="flex flex-wrap gap-2">
313	                {attachments.map((a) => (
314	                  <span
315	                    key={a.id}
316	                    className="card flex max-w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-xs text-slate-200"
317	                    title={`${a.filename} — ${formatBytes(a.size)}`}
318	                  >
319	                    <span className="flex-none text-brand-300"><Icon.paperclip size={13} /></span>
320	                    <span className="max-w-[12rem] truncate">{a.filename}</span>
321	                    <span className="flex-none text-slate-500">{formatBytes(a.size)}</span>
322	                    <button
323	                      type="button"
324	                      onClick={() => removeAttachment(a.id)}
325	                      disabled={sending}
326	                      className="btn-ghost flex-none rounded p-0.5 text-slate-400 hover:text-white disabled:opacity-40"
327	                      aria-label={`Remove ${a.filename}`}
328	                    >
329	                      <Icon.close size={12} />
330	                    </button>
331	                  </span>
332	                ))}
333	              </div>
334	            </div>
335	          )}
336	        </div>
337	
338	        {/* Hidden file input driving the Attach button */}
339	        <input
340	          ref={fileInputRef}
341	          type="file"
342	          multiple
343	          className="hidden"
344	          onChange={(e) => {
345	            if (e.target.files?.length) void addFiles(e.target.files);
346	            e.target.value = ""; // allow re-selecting the same file
347	          }}
348	        />
349	
350	        {/* Footer */}
351	        <div className="flex items-center justify-between gap-3 border-t border-white/[0.08] bg-white/[0.02] px-5 py-3">
352	          <div className="flex min-w-0 items-center gap-2">
353	            <button
354	              type="button"
355	              onClick={() => fileInputRef.current?.click()}
356	              disabled={sending || reading || attachments.length >= MAX_ATTACHMENTS}
357	              className="btn-ghost flex flex-none items-center gap-1.5 rounded-lg px-2 py-1.5 text-slate-300 disabled:opacity-40"
358	              title="Attach files"
359	              aria-label="Attach files"
360	            >
361	              <Icon.paperclip size={16} />
362	              <span className="hidden text-xs font-medium sm:inline">Attach</span>
363	            </button>
364	            <span className="min-w-0 truncate text-xs text-red-300">
365	              {error || (reading ? "Reading files…" : "")}
366	            </span>
367	          </div>
368	          <div className="flex flex-none items-center gap-2">
369	            <span className="hidden text-[11px] text-slate-600 sm:inline">
370	              <span className="kbd">⌘/Ctrl</span> + <span className="kbd">Enter</span>
371	            </span>
372	            <button onClick={onClose} className="btn-secondary" disabled={sending}>
373	              Discard
374	            </button>
375	            <button onClick={submit} className="btn-primary" disabled={sending || reading || !to.trim()}>
376	              {sending ? "Sending…" : "Send"}
377	            </button>
378	          </div>
379	        </div>
380	      </div>
381	    </div>
382	  );
383	}
384	
385	function FieldRow({ label, children }: { label: string; children: React.ReactNode }) {
386	  return (
387	    <label className="flex items-center gap-3 border-b border-white/[0.06] px-5 py-2.5">
388	      <span className="w-14 flex-none text-xs font-medium uppercase tracking-wide text-slate-500">{label}</span>
389	      <span className="flex flex-1 items-center">{children}</span>
390	    </label>
391	  );
392	}
