74	/**
75	 * Build the download URL for one attachment part of one message.
76	 *
77	 * `mailbox` is NOT optional decoration. `app/api/mail/attachment/route.ts` calls
78	 * `resolveMailbox(mailbox)`, and `resolveMailbox(undefined)` resolves the
79	 * account's DEFAULT (oldest) mailbox — not the one being read. The reading pane
80	 * used to build this href by hand and omit the parameter, so on an account with
81	 * two mailboxes every attachment opened from the second one was fetched with
82	 * `<uid>` interpreted against the FIRST mailbox's IMAP session. IMAP UIDs are
83	 * per-folder counters that start at 1 in every mailbox, so that lookup usually
84	 * SUCCEEDS and returns a different message's file — the wrong document, handed
85	 * over with no error anywhere. Centralised here so it cannot be forgotten again.
86	 */
87	export function mailAttachmentUrl(opts: {
88	  folder: string;
89	  uid: number;
90	  /** Either the bare IMAP part id or the `"<uid>:<partId>"` attachment id. */
91	  part: string;
92	  /** The mailbox the message was read from. */
93	  mailbox?: string;
94	}): string {
95	  const qs = new URLSearchParams({
96	    folder: opts.folder,
97	    uid: String(opts.uid),
98	    part: opts.part,
99	  });
100	  if (opts.mailbox) qs.set("mailbox", opts.mailbox);
101	  return `/api/mail/attachment?${qs.toString()}`;
102	}
