23	/**
24	 * SMTP config comes from the Setting table (admin-editable) with env fallback.
25	 * Keys: smtp_host, smtp_port, smtp_user, smtp_pass, smtp_from, smtp_secure.
26	 * If nothing is configured, falls back to a local sendmail/Postfix relay on :25.
27	 */
28	/**
29	 * The stored SMTP password, decrypted — tolerating a LEGACY plaintext row.
30	 *
31	 * `smtp_pass` is now written through `encryptSecret` (iv:tag:ciphertext), but a
32	 * value saved before that change is bare plaintext. `decryptSecret` returns null
33	 * on a value that is not in the encrypted shape, so a null result means "this was
34	 * never encrypted" — fall back to the raw stored value. Once an operator re-saves
35	 * the SMTP settings, the row is encrypted and this fallback stops being taken.
36	 */
37	function smtpPassPlain(stored: string | undefined): string {
38	  if (!stored) return "";
39	  const dec = decryptSecret(stored);
40	  return dec ?? stored;
41	}
42	
43	async function loadSmtp() {
44	  const rows = await db.setting.findMany({
45	    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_from", "smtp_secure"] } },
46	  });
47	  const s = Object.fromEntries(rows.map((r) => [r.key, r.value]));
48	  const host = s.smtp_host || process.env.SMTP_HOST || "";
49	  const from = s.smtp_from || process.env.SMTP_FROM || `Nxeon <no-reply@${(process.env.APP_URL ?? "localhost").replace(/^https?:\/\//, "")}>`;
50	  return {
51	    host,
52	    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
53	    user: s.smtp_user || process.env.SMTP_USER || "",
54	    pass: smtpPassPlain(s.smtp_pass) || process.env.SMTP_PASS || "",
55	    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
56	    from,
57	  };
58	}
59	
60	export async function mailConfigured(): Promise<boolean> {
61	  const c = await loadSmtp();
62	  return !!c.host || process.env.NXEON_LOCAL_MAIL === "1";
63	}
64	
65	function transport(c: Awaited<ReturnType<typeof loadSmtp>>) {
66	  if (!c.host) {
67	    // Local MTA fallback (Postfix/sendmail on the host)
68	    return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
69	  }
70	  // When the SMTP host is an internal IP (e.g. the mail VM at 10.20.0.10) but the
71	  // server presents a cert for its hostname (mail.nxeon.cloud), TLS validation
72	  // fails on an IP mismatch. `SMTP_TLS_SERVERNAME` lets us keep cert verification
73	  // on while telling TLS the name to validate against (and sets SNI accordingly).
74	  const servername = process.env.SMTP_TLS_SERVERNAME || undefined;
75	  return nodemailer.createTransport({
76	    host: c.host,
77	    port: c.port,
78	    secure: c.secure,
79	    auth: c.user ? { user: c.user, pass: c.pass } : undefined,
80	    ...(servername ? { tls: { servername } } : {}),
81	  });
82	}
