89	/**
90	 * Build the invoice attachment for an email. There is no PDF library installed
91	 * (and we can't add dependencies), so we attach the branded, print-ready
92	 * invoice HTML produced by `lib/invoices.ts` — recipients open it and use their
93	 * browser's Print → Save as PDF, matching the on-site download route.
94	 */
95	async function invoiceAttachment(invoiceId: string): Promise<MailAttachment | null> {
96	  try {
97	    const invoice = await db.invoice.findUnique({
98	      where: { id: invoiceId },
99	      include: { user: { select: { name: true, email: true } } },
100	    });
101	    if (!invoice) return null;
102	    // Use the SAME branding the dashboard and the download route use, so the
103	    // invoice a customer receives by email carries the identifier they can quote
104	    // back at you — and the seller block, which only reaches emailed invoices
105	    // through this path. Previously this hardcoded `#00012`-style numbering while
106	    // every on-screen copy showed `INV-00012`: the customer and the support agent
107	    // would have been reading two different invoice numbers for one invoice.
108	    const branding = await invoiceBranding();
109	    const html = renderInvoiceHTML(invoice, invoice.user, branding);
110	    const number = formatInvoiceNumber(invoice.number, branding.numberPrefix);
111	    return { filename: `nxeon-invoice-${number}.html`, content: html, contentType: "text/html; charset=utf-8" };
112	  } catch (e) {
113	    console.error("[mailer] failed to build invoice attachment:", e);
114	    return null;
115	  }
116	}
