118	export type SendMailOpts = {
119	  to: string;
120	  /** Explicit subject. Optional when `template` is provided. */
121	  subject?: string;
122	  /** Explicit pre-rendered HTML. Optional when `template` is provided. */
123	  html?: string;
124	  text?: string;
125	  /** DB template key — when set (and no explicit `html`), the body is rendered via `renderTemplate`. */
126	  template?: string;
127	  /** Variables for `{{placeholders}}` when rendering from a template. */
128	  vars?: Record<string, unknown>;
129	  /** Attribution for the EmailLog row. */
130	  userId?: string | null;
131	  /** When set, attaches the invoice (auto for receipt/invoice_new/renewal_reminder templates). */
132	  invoiceId?: string;
133	  /** Extra attachments. */
134	  attachments?: MailAttachment[];
135	  /**
136	   * What KIND of message this is, for the notification-preference policy in
137	   * `lib/prefs.ts`. Supply it together with `userId` and this function enforces
138	   * the customer's choice centrally — see the gate below.
139	   *
140	   * Omitting it means "always send", which is the safe default: a message must
141	   * never be dropped because someone forgot to classify it.
142	   */
143	  kind?: NotifyKind;
144	};
