146	/**
147	 * Send an email. Never throws — logs and returns false on failure so callers
148	 * don't break flows. EVERY attempt is written to `EmailLog` (SENT on success,
149	 * FAILED + error otherwise) for the admin Logs viewer.
150	 *
151	 * NOTIFICATION PREFERENCES are enforced HERE, not at the call sites.
152	 * `User.notificationPrefs` was a column the customer edited and nothing read, so
153	 * turning off "email me about billing" changed nothing. Gating each send site
154	 * individually would have fixed today's sites and left every future one to
155	 * re-introduce the bug; gating centrally means a new send site inherits the
156	 * policy automatically and per-site checks become defence in depth.
157	 *
158	 * Two deliberate properties, both fail-open:
159	 *   - no `kind` (or no `userId`) → send. Unclassified is never silenced.
160	 *   - `mayDeliverTo` returns true for anything non-suppressible without touching
161	 *     the database, and also on a lookup error. A payment-failure or suspension
162	 *     warning must not be lost because a preference read failed.
163	 */
164	export async function sendMail(opts: SendMailOpts): Promise<boolean> {
165	  // Preference gate. CRITICAL kinds (payment failed, suspension, security
166	  // changes, data loss…) are declared non-suppressible in lib/prefs.ts and short
167	  // -circuit to true, so this costs nothing on the paths that matter most.
168	  if (opts.kind && opts.userId) {
169	    const allowed = await mayDeliverTo(opts.userId, opts.kind, "email");
170	    if (!allowed) {
171	      console.log(`[mail] suppressed ${opts.kind} to user ${opts.userId} by preference`);
172	      return false;
173	    }
174	  }
175	
176	  // Resolve subject/html: prefer explicit values, otherwise render the template.
177	  let subject = opts.subject ?? "";
178	  let html = opts.html ?? "";
179	  const templateKey = opts.template ?? null;
180	
181	  if (templateKey && !opts.html) {
182	    const rendered = await renderTemplate(templateKey, opts.vars ?? {});
183	    subject = opts.subject ?? rendered.subject;
184	    html = rendered.html;
185	  }
186	
187	  // Assemble attachments (invoice auto-attaches for the relevant templates).
188	  const attachments: MailAttachment[] = [...(opts.attachments ?? [])];
189	  const wantInvoice = opts.invoiceId && (!templateKey || INVOICE_ATTACH_TEMPLATES.has(templateKey));
190	  if (wantInvoice && opts.invoiceId) {
191	    const att = await invoiceAttachment(opts.invoiceId);
192	    if (att) attachments.push(att);
193	  }
194	
195	  try {
196	    const c = await loadSmtp();
197	    if (!c.host && process.env.NXEON_LOCAL_MAIL !== "1") {
198	      console.warn("[mailer] not configured — skipping email:", subject);
199	      await recordEmail(opts.to, subject, templateKey, html, "FAILED", "SMTP not configured", opts.userId);
200	      return false;
201	    }
202	    const t = transport(c);
203	    await t.sendMail({
204	      from: c.from,
205	      to: opts.to,
206	      subject,
207	      html,
208	      text: opts.text ?? html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim(),
209	      attachments: attachments.length ? attachments : undefined,
210	    });
211	    await recordEmail(opts.to, subject, templateKey, html, "SENT", null, opts.userId);
212	    return true;
213	  } catch (e) {
214	    console.error("[mailer] send failed:", e);
215	    await recordEmail(opts.to, subject, templateKey, html, "FAILED", String((e as Error)?.message ?? e), opts.userId);
216	    return false;
217	  }
218	}
