522	/** Set or clear the \Seen or \Flagged flag on a message. */
523	export async function setFlag(
524	  folder: string,
525	  uid: number,
526	  flag: "seen" | "flagged",
527	  value: boolean,
528	  mailboxAddress?: string,
529	): Promise<void> {
530	  const { user, cred } = await resolveMailbox(mailboxAddress);
531	  enforceRateLimit(`mail:flag:${user.id}`, { max: 240, windowMs: 60 * 1000 });
532	  const imapFlag = flag === "seen" ? "\\Seen" : "\\Flagged";
533	  await withMailbox(cred, folder, async (client) => {
534	    if (value) await client.messageFlagsAdd(String(uid), [imapFlag], { uid: true });
535	    else await client.messageFlagsRemove(String(uid), [imapFlag], { uid: true });
536	  });
537	}
