540	export async function moveMessage(
541	  folder: string,
542	  uid: number,
543	  toFolder: string,
544	  mailboxAddress?: string,
545	): Promise<void> {
546	  const { user, cred } = await resolveMailbox(mailboxAddress);
547	  enforceRateLimit(`mail:move:${user.id}`, { max: 120, windowMs: 60 * 1000 });
548	  await withMailbox(cred, folder, async (client) => {
