553	/** Delete a message: move to Trash, or permanently expunge if already in Trash. */
554	export async function deleteMessage(folder: string, uid: number, mailboxAddress?: string): Promise<void> {
555	  const { user, cred } = await resolveMailbox(mailboxAddress);
556	  enforceRateLimit(`mail:delete:${user.id}`, { max: 120, windowMs: 60 * 1000 });
557	
558	  await withImap(cred, async (client) => {
559	    // Determine the Trash folder path.
560	    let trashPath = "Trash";
561	    try {
562	      const list = await client.list();
563	      const trash = list.find((f) => folderRole(f.path, f.specialUse) === "trash");
564	      if (trash) trashPath = trash.path;
565	    } catch {
566	      /* fall back to "Trash" */
567	    }
568	
569	    const inTrash = folderRole(folder) === "trash" || folder === trashPath;
570	    const lock = await client.getMailboxLock(folder);
571	    try {
572	      if (inTrash) {
573	        await client.messageDelete(String(uid), { uid: true });
574	      } else {
575	        await client.messageMove(String(uid), trashPath, { uid: true });
576	      }
577	    } finally {
578	      lock.release();
579	    }
580	  });
