1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { checkRateLimit } from "@/lib/rate-limit";
5	import { trustedClientIp } from "@/app/api/_lib/client-ip";
6	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
7	
8	export const runtime = "nodejs";
9	
10	/**
11	 * Public live-chat endpoint used by <ChatWidget/>.
12	 *
13	 * POST /api/chat  — start or continue a conversation for a visitorId.
14	 * GET  /api/chat?visitorId=…  — poll the visitor's open conversation.
15	 *
16	 * Everything is scoped strictly by the client-supplied `visitorId`; we never
17	 * return another visitor's data. Signed-in customers additionally get their
18	 * `userId` stamped on the conversation. Unauthenticated + write-heavy, so the
19	 * POST path is rate-limited per IP.
20	 */
21	
22	function clip(v: unknown, max: number): string | null {
23	  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
24	}
25	
26	type AttachmentRow = { id: string; mime: string; sizeBytes: number } | null;
27	
28	function serialize(convo: {
29	  id: string;
30	  status: string;
31	  name: string | null;
32	  email: string | null;
33	  messages: {
34	    id: string;
35	    sender: string;
36	    body: string;
37	    createdAt: Date;
38	    attachment?: AttachmentRow;
39	  }[];
40	}) {
41	  return {
42	    conversation: {
43	      id: convo.id,
44	      status: convo.status,
45	      name: convo.name,
46	      email: convo.email,
47	    },
48	    messages: convo.messages.map((m) => ({
49	      id: m.id,
50	      sender: m.sender,
51	      body: m.body,
52	      createdAt: m.createdAt.toISOString(),
53	      attachment: m.attachment
54	        ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
55	        : null,
56	    })),
57	  };
58	}
59	
60	export async function POST(req: Request) {
61	  const rl = checkRateLimit(`chat:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
62	  if (!rl.ok) {
63	    return NextResponse.json(
64	      { error: "Too many messages. Please slow down." },
65	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
66	    );
67	  }
68	
69	  const raw = (await req.json().catch(() => ({}))) as Record<string, unknown>;
70	  const visitorId = clip(raw.visitorId, 100);
71	  const body = clip(raw.body, 5000);
72	  const name = clip(raw.name, 120);
73	  const email = clip(raw.email, 200);
74	
75	  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
76	  if (!body) return NextResponse.json({ error: "Message cannot be empty." }, { status: 400 });
77	
78	  const user = await currentUser();
79	
80	  // Continue the visitor's existing open conversation, else start a new one.
81	  let convo = await db.chatConversation.findFirst({
82	    where: { visitorId, status: "OPEN" },
83	    orderBy: { lastMessageAt: "desc" },
84	    select: { id: true, name: true, email: true },
85	  });
86	
87	  if (!convo) {
88	    convo = await db.chatConversation.create({
89	      data: {
90	        visitorId,
91	        userId: user?.id ?? null,
92	        name: name ?? user?.name ?? null,
93	        email: email ?? user?.email ?? null,
94	      },
95	      select: { id: true, name: true, email: true },
96	    });
97	  }
98	
99	  await db.$transaction([
100	    db.chatMessage.create({
101	      data: { conversationId: convo.id, sender: "visitor", body },
102	    }),
103	    db.chatConversation.update({
104	      where: { id: convo.id },
105	      data: {
106	        unreadForAgent: true,
107	        lastMessageAt: new Date(),
108	        // Backfill identity / link account if it arrives after creation.
109	        ...(user?.id ? { userId: user.id } : {}),
110	        ...(name && !convo.name ? { name } : {}),
111	        ...(email && !convo.email ? { email } : {}),
112	      },
113	    }),
114	  ]);
115	
116	  const full = await db.chatConversation.findUnique({
117	    where: { id: convo.id },
118	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
119	  });
120	  return NextResponse.json(serialize(full!), { headers: NO_STORE_HEADERS });
121	}
122	
123	export async function GET(req: Request) {
124	  const url = new URL(req.url);
125	  const visitorId = clip(url.searchParams.get("visitorId"), 100);
126	  if (!visitorId) {
127	    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
128	  }
129	
130	  const convo = await db.chatConversation.findFirst({
131	    where: { visitorId, status: "OPEN" },
132	    orderBy: { lastMessageAt: "desc" },
133	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
134	  });
135	
136	  if (!convo) {
137	    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
138	  }
139	
140	  // Reading the thread clears the visitor-facing unread flag.
141	  if (convo.unreadForUser) {
142	    await db.chatConversation
143	      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
144	      .catch(() => {});
145	  }
146	
147	  // The whole support transcript, plus the name/email the visitor gave. The
148	  // `?visitorId=` in the URL is the ONLY thing scoping it, which makes the URL
149	  // itself the secret — precisely the shape a shared cache must never store.
150	  return NextResponse.json(serialize(convo), { headers: NO_STORE_HEADERS });
151	}
