137	  // If the visitor is a signed-in customer, drop them a notification.
138	  if (convo.userId) {
139	    await db.notification
140	      .create({
141	        data: {
142	          userId: convo.userId,
143	          title: "New reply in your live chat",
144	          href: "/dashboard",
145	        },
146	      })
147	      .catch(() => {});
148	  }
149	
150	  revalidatePath("/admin/chat");
151	  return { ok: true };
