154	/**
155	 * Staff reply carrying an image attachment. Same authorization and side effects
156	 * as `replyToConversation` (requireArea("support"), notify, assign, unread) but
157	 * the message body may be empty and it stores a signature-verified image in
158	 * Postgres. All security checks (allow-list, magic-number, 5 MB cap, SVG
159	 * rejection) run in `validateImageBytes` — the client cannot bypass them.
160	 */
161	export async function replyWithAttachment(
162	  formData: FormData
163	): Promise<{ error?: string; ok?: boolean }> {
164	  const staff = await requireArea("support");
165	
166	  // Throttle staff uploads defensively (shared limiter, keyed by staff id).
167	  const rl = checkRateLimit(`chat-upload:${staff.id}`, { max: 30, windowMs: 60_000 });
168	  if (!rl.ok) return { error: "Too many uploads. Please slow down." };
169	
170	  const id = formData.get("conversationId");
171	  const rawBody = formData.get("body");
172	  const file = formData.get("file");
173	
174	  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
175	  const body = typeof rawBody === "string" ? rawBody.trim().slice(0, 5000) : "";
176	  if (!(file instanceof File)) return { error: "No image provided." };
177	  if (file.size > 5 * 1024 * 1024) return { error: "Image is larger than 5 MB." };
178	
179	  const convo = await db.chatConversation.findUnique({ where: { id } });
180	  if (!convo) return { error: "Conversation not found." };
181	
182	  const bytes = Buffer.from(await file.arrayBuffer());
183	  const check = validateImageBytes(bytes, file.type);
184	  if (!check.ok) return { error: check.error };
185	
186	  await db.$transaction(async (tx) => {
187	    const msg = await tx.chatMessage.create({
188	      data: { conversationId: id, sender: "agent", body },
189	    });
190	    await tx.chatAttachment.create({
191	      data: {
192	        messageId: msg.id,
193	        mime: check.mime,
194	        sizeBytes: check.bytes.length,
195	        data: new Uint8Array(check.bytes),
196	      },
197	    });
198	    await tx.chatConversation.update({
199	      where: { id },
200	      data: {
201	        status: "OPEN",
202	        unreadForUser: true,
203	        unreadForAgent: false,
204	        assignedToId: staff.id,
205	        lastMessageAt: new Date(),
206	      },
207	    });
208	  });
209	
210	  if (convo.userId) {
211	    await db.notification
212	      .create({
213	        data: {
214	          userId: convo.userId,
215	          title: "New reply in your live chat",
216	          href: "/dashboard",
217	        },
218	      })
219	      .catch(() => {});
220	  }
221	
222	  revalidatePath("/admin/chat");
223	  return { ok: true };
224	}
