19	/**
20	 * Admin live-chat inbox. Two-pane layout: a conversation list (unread + newest
21	 * first) and a thread view with a reply box. Polls `listConversations` every
22	 * few seconds so new visitor messages appear without a manual refresh.
23	 */
24	
25	type Attachment = { id: string; mime: string; sizeBytes: number };
26	type Msg = {
27	  id: string;
28	  sender: string;
29	  body: string;
30	  createdAt: string;
31	  attachment?: Attachment | null;
32	};
33	type Convo = {
