49	// Client-side pre-checks only; replyWithAttachment re-validates by signature.
50	const ACCEPT_IMAGES = "image/png,image/jpeg,image/gif,image/webp";
51	const ALLOWED_IMAGE_TYPES = new Set(["image/png", "image/jpeg", "image/gif", "image/webp"]);
52	const MAX_IMAGE_BYTES = 5 * 1024 * 1024;
