54	function imageError(file: File): string | null {
55	  if (!ALLOWED_IMAGE_TYPES.has(file.type)) return "Only PNG, JPEG, GIF, or WEBP images.";
56	  if (file.size > MAX_IMAGE_BYTES) return "Image must be 5 MB or smaller.";
57	  return null;
