80	      if (pendingImage) URL.revokeObjectURL(pendingImage.url);
81	    };
82	  }, [pendingImage]);
83	
84	  function pickImage(file: File | null | undefined) {
85	    if (!file) return;
86	    const err = imageError(file);
87	    if (err) {
88	      setError(err);
89	      return;
90	    }
91	    setError("");
92	    setPendingImage((prev) => {
93	      if (prev) URL.revokeObjectURL(prev.url);
94	      return { file, url: URL.createObjectURL(file) };
95	    });
96	  }
97	
98	  function clearImage() {
99	    setPendingImage((prev) => {
100	      if (prev) URL.revokeObjectURL(prev.url);
101	      return null;
102	    });
103	    if (fileInputRef.current) fileInputRef.current.value = "";
104	  }
105	
106	  function onPaste(e: ClipboardEvent) {
107	    const item = Array.from(e.clipboardData?.items ?? []).find((i) =>
108	      i.type.startsWith("image/")
109	    );
110	    if (item) {
111	      const file = item.getAsFile();
112	      if (file) {
113	        e.preventDefault();
114	        pickImage(file);
115	      }
116	    }
117	  }
