123	    } catch {
124	      /* transient — next poll retries */
125	    }
126	  }, []);
127	
128	  useEffect(() => {
129	    const t = setInterval(refresh, POLL_MS);
130	    return () => clearInterval(t);
131	  }, [refresh]);
132	
133	  const selected = convos.find((c) => c.id === selectedId) ?? null;
134	
135	  useEffect(() => {
136	    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight });
137	  }, [selected?.messages.length, selectedId]);
