// Pure helpers that turn the rich-text composer's contentEditable HTML into a
// safe, deliverable mail body. No React, no DOM APIs — just string work — so it
// runs identically in the browser (the Composer) and under `node:test`.
//
// The security contract mirrors the rest of the mail client: NOTHING leaves the
// composer without going through `safeHtml` (lib/mail/render.ts), the same
// sanitiser the IMAP engine runs on inbound bodies. The composed HTML is
// attacker-influenceable (a user can paste anything), and this platform sends
// real mail, so the toolbar must never become an XSS vector in the recipient's
// client.
//
// Inline images: browsers paste images into a contentEditable as
// `data:image/…;base64,…` URIs. `safeHtml` deliberately neutralises ALL `data:`
// URLs (a `data:text/html` src is a script vector), so a pasted image would be
// silently blanked to `src="#"` if we handed it straight to the sanitiser.
// Instead we lift each raster data-image OUT of the HTML first, swap its `src`
// for a `cid:` reference, and hand the bytes back as inline attachments the send
// path attaches with that Content-ID. `cid:` is not a dangerous scheme, so it
// survives `safeHtml` untouched, and nodemailer assembles a multipart/related
// message every mail client renders inline. Anything that is NOT a base64 raster
// data-image (e.g. `data:text/html`, `data:image/svg+xml`) is left for
// `safeHtml` to neutralise — dropped on purpose, never delivered.

import { safeHtml } from "@/lib/mail/render";

export type InlineImage = {
  cid: string; // Content-ID, referenced as `src="cid:<cid>"`
  filename: string;
  contentType: string; // e.g. "image/png"
  contentBase64: string; // raw base64, no "data:*;base64," prefix
};

// A raster image the browser is willing to inline. SVG is excluded on purpose:
// it can carry script, and an inline SVG attachment is a needless XSS surface.
const RASTER_SUBTYPES = new Set(["png", "jpeg", "jpg", "gif", "webp", "bmp"]);

// <img … src="data:image/<subtype>;base64,<data>" …> in either quote style.
const DATA_IMG =
  /<img\b[^>]*?\ssrc\s*=\s*(["'])data:image\/([a-z0-9.+-]+);base64,([a-z0-9+/=\s]*)\1[^>]*>/gi;

function extFor(subtype: string): string {
  const s = subtype.toLowerCase();
  if (s === "jpeg" || s === "jpg") return "jpg";
  if (s === "svg+xml") return "svg";
  return s.replace(/[^a-z0-9]/g, "") || "img";
}

/**
 * Lift base64 raster data-images out of `html`, replacing each `src` with a
 * `cid:` reference and returning the extracted bytes. Non-raster / non-base64
 * data-images are left in place (to be neutralised later by `safeHtml`).
 */
export function extractInlineImages(html: string): { html: string; images: InlineImage[] } {
  const images: InlineImage[] = [];
  let n = 0;

  const out = (html || "").replace(DATA_IMG, (tag: string, _q: string, subtype: string, b64: string) => {
    if (!RASTER_SUBTYPES.has(subtype.toLowerCase())) return tag; // safeHtml will handle it
    const clean = b64.replace(/\s+/g, "");
    if (!clean) return tag;
    n += 1;
    const cid = `nximg-${n}-${Math.random().toString(36).slice(2, 10)}@nxeon`;
    images.push({
      cid,
      filename: `image-${n}.${extFor(subtype)}`,
      contentType: `image/${subtype.toLowerCase() === "jpg" ? "jpeg" : subtype.toLowerCase()}`,
      contentBase64: clean,
    });
    // Swap ONLY this tag's src value; leave every other attribute intact.
    return tag.replace(/\ssrc\s*=\s*(["'])data:[^"']*\1/i, ` src="cid:${cid}"`);
  });

  return { html: out, images };
}

/**
 * The one entry point the Composer uses. Extracts inline images to `cid:`
 * references, then runs the composed HTML through `safeHtml`. The returned
 * `html` is safe to send as-is; `images` are the inline attachments the send
 * path must carry with matching Content-IDs.
 */
export function prepareComposedBody(rawHtml: string): { html: string; images: InlineImage[] } {
  const { html, images } = extractInlineImages(rawHtml || "");
  return { html: safeHtml(html), images };
}

/**
 * Derive the plain-text alternative from the composer's own `innerText`. The
 * editor already gives us caret-accurate text with real newlines, so we only
 * normalise trailing whitespace. Kept here so the plain part is produced the
 * same way everywhere and stays testable.
 */
export function plainTextFromEditor(innerText: string): string {
  return (innerText || "").replace(/ /g, " ").replace(/[ \t]+\n/g, "\n").replace(/\s+$/,"");
}

