const [subject, setSubject] = useState(draft.subject);
const [sending, setSending] = useState(false);
const [error, setError] = useState<string | null>(null);
const [attachments, setAttachments] = useState<Attachment[]>([]);
const [reading, setReading] = useState(false);
const [dragging, setDragging] = useState(false);
// The rich editor is a contentEditable region (inherently ref-driven). We
// track only whether it is EMPTY so the placeholder can show — the authoritative
// HTML is always read from the ref at submit time, never from React state, so
// there is no controlled/uncontrolled reset to lose the customer's draft.
const [editorEmpty, setEditorEmpty] = useState(!draft.body.trim());

const fileInputRef = useRef<HTMLInputElement>(null);
const editorRef = useRef<HTMLDivElement>(null);
const dragDepth = useRef(0); // ignore nested dragenter/dragleave events

// Seed the editor once from the draft's plaintext body (escaped, newlines →
// <br>). Reply/forward drafts start with blank lines; "new" starts empty.
useEffect(() => {
  const el = editorRef.current;
  if (!el) return;
  const seed = draft.body
    ? draft.body.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\n/g, "<br>")
    : "";
  el.innerHTML = seed;
  setEditorEmpty(!el.textContent?.trim() && !el.querySelector("img"));
  // Seed exactly once on mount — the ref is stable and never re-seeded.
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, []);

useEffect(() => {
  const onKey = (e: KeyboardEvent) => {
    if (e.key === "Escape" && !sending) onClose();
    if ((e.metaKey || e.ctrlKey) && e.key === "Enter") void submit();
  };
  window.addEventListener("keydown", onKey);
  return () => window.removeEventListener("keydown", onKey);
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [to, cc, subject, sending, attachments]);

function syncEmpty() {
  const el = editorRef.current;
  setEditorEmpty(!!el && !el.textContent?.trim() && !el.querySelector("img"));
}

// Apply a formatting command to the current selection inside the editor.
function format(command: string, value?: string) {
  editorRef.current?.focus();
  try {
    document.execCommand(command, false, value);
  } catch {
    /* execCommand is unavailable in some embeddings — degrade to plain text */
  }
  syncEmpty();
}

// Insert a pasted/embedded image as a data: URI at the caret. It is converted
// to an inline cid attachment by prepareComposedBody() at send time.
function insertInlineImage(file: File) {
  if (file.size > MAX_ATTACHMENTS_TOTAL_BYTES) {
    setError(`Images must be under ${formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}.`);
    return;
  }
  const reader = new FileReader();
  reader.onload = () => {
    const url = String(reader.result || "");
    if (!url.startsWith("data:image/")) return;
    editorRef.current?.focus();
    try {
      document.execCommand("insertImage", false, url);
    } catch {
      /* ignore — nothing inserted */
    }
    syncEmpty();
  };
  reader.readAsDataURL(file);
}

// Paste: images go inline; everything else keeps the browser's formatted paste
// (sanitised at send). Formatted copy-paste is therefore preserved reasonably.
function onEditorPaste(e: React.ClipboardEvent) {
  const items = Array.from(e.clipboardData?.items ?? []);
  const image = items.find((i) => i.kind === "file" && i.type.startsWith("image/"));
  if (image) {
    const file = image.getAsFile();
    if (file) {
      e.preventDefault();
      setError(null);
      insertInlineImage(file);
    }
  }
}

