} from "../components/customer/mail/compose-html.ts";

// A 1x1 transparent PNG, used as a stand-in for a pasted image.
const PNG_B64 =
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==";

// ---------------------------------------------------------------------------
// Sanitisation: the composed body must never carry an XSS vector to a recipient.
// ---------------------------------------------------------------------------

test("prepareComposedBody strips <script> elements and their content", () => {
  const { html } = prepareComposedBody(`hello<script>alert(1)</script> world`);
  assert.ok(!/<script/i.test(html), "no <script> tag survives");
  assert.ok(!/alert\(1\)/.test(html), "script body is removed");
  assert.match(html, /hello/);
  assert.match(html, /world/);
});

test("prepareComposedBody removes inline event handlers", () => {
  const { html } = prepareComposedBody(`<img src="cid:x" onerror="steal()">`);
  assert.ok(!/onerror/i.test(html), "onerror handler is stripped");
});

test("prepareComposedBody neutralises javascript: links", () => {
  const { html } = prepareComposedBody(`<a href="javascript:steal()">click</a>`);
  assert.ok(!/javascript:/i.test(html), "javascript: scheme is neutralised");
  assert.match(html, /href="#"/, "the href is replaced with a safe placeholder");
});

test("prepareComposedBody neutralises a data:text/html image (script vector)", () => {
  const { html, images } = prepareComposedBody(
    `<img src="data:text/html;base64,PHNjcmlwdD4=">`,
  );
  assert.equal(images.length, 0, "a non-raster data URI is NOT taken as an inline image");
  assert.ok(!/data:text\/html/i.test(html), "the dangerous data URI does not survive");
});

test("prepareComposedBody drops an inline SVG data image rather than attaching it", () => {
  const { images } = prepareComposedBody(
    `<img src="data:image/svg+xml;base64,PHN2Zz48L3N2Zz4=">`,
  );
  assert.equal(images.length, 0, "SVG is excluded from inline-image extraction");
});

// ---------------------------------------------------------------------------
// Formatting is preserved so "what you compose is what they get".
// ---------------------------------------------------------------------------

test("prepareComposedBody preserves basic formatting markup", () => {
  const src = `<b>bold</b> <i>it</i> <u>u</u> <span style="color:#ff0000">red</span><ul><li>one</li></ul>`;
  const { html } = prepareComposedBody(src);
  assert.match(html, /<b>bold<\/b>/);
  assert.match(html, /<i>it<\/i>/);
  assert.match(html, /<u>u<\/u>/);
  assert.match(html, /color:#ff0000/, "inline colour style is kept");
  assert.match(html, /<ul><li>one<\/li><\/ul>/, "list markup is kept");
});

// ---------------------------------------------------------------------------
// Inline images: pasted data-images become deliverable cid: attachments.
// ---------------------------------------------------------------------------

test("extractInlineImages lifts a base64 raster image out to a cid attachment", () => {
  const { html, images } = extractInlineImages(
    `<p>see</p><img src="data:image/png;base64,${PNG_B64}" alt="shot">`,
  );
  assert.equal(images.length, 1);
  assert.equal(images[0].contentType, "image/png");
  assert.equal(images[0].contentBase64, PNG_B64, "raw base64 is carried through unchanged");
  assert.match(html, /src="cid:nximg-1-[a-z0-9]+@nxeon"/, "src now references the cid");
  assert.ok(!/data:image/i.test(html), "no data URI remains in the body");
  assert.match(html, /alt="shot"/, "other attributes on the img are preserved");
});

test("a cid image reference survives sanitisation intact", () => {
  const { html, images } = prepareComposedBody(
    `<img src="data:image/png;base64,${PNG_B64}">`,
  );
  assert.equal(images.length, 1);
  assert.match(html, new RegExp(`src="cid:${images[0].cid.replace(/[.+@]/g, "\\$&")}"`));
});

test("multiple inline images get distinct cids", () => {
  const { images } = extractInlineImages(
    `<img src="data:image/png;base64,${PNG_B64}"><img src="data:image/gif;base64,R0lGODlhAQABAAAAACw=">`,
  );
  assert.equal(images.length, 2);
  assert.notEqual(images[0].cid, images[1].cid);
  assert.equal(images[1].contentType, "image/gif");
});

test("plainTextFromEditor trims trailing whitespace and normalises nbsp", () => {
  const out = plainTextFromEditor("hello there\n\n");
  assert.equal(out, "hello there");
});

// ---------------------------------------------------------------------------
// SOURCE TRIPWIRES — the cardinal rule: a control whose outcome isn't verified
// must not ship. These guard the two ends of the HTML body's journey.
// ---------------------------------------------------------------------------

function readSrc(rel: string): string {
  return stripCommentsAndStrings(readFileSync(fileURLToPath(new URL(rel, import.meta.url)), "utf8"));
}

test("Composer routes the composed HTML through prepareComposedBody before sending", () => {
  const src = readSrc("../components/customer/mail/Composer.tsx");
  assert.match(src, /prepareComposedBody\(/, "the toolbar's HTML must be sanitised, never sent raw");
  assert.match(src, /editorRef\.current\?\.innerHTML/, "the body is read from the editor DOM at submit");
});

test("the send action sanitises the outbound HTML body server-side", () => {
  const src = readSrc("../lib/actions-mail.ts");
  assert.match(src, /safeHtml\(payload\.html\)/, "server must re-sanitise the body before SMTP");
});

test("the send action carries inline-image cids through to the mail", () => {
  const src = readSrc("../lib/actions-mail.ts");
  assert.match(src, /cid:/, "inline attachments must be built with their Content-ID");
  assert.match(src, /contentDisposition:/, "inline images must be marked inline");
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { stripCommentsAndStrings } from "./_source-tools.ts";
import {
  isTypingActive,
  markTyping,
  readTyping,
  TYPING_TTL_MS,
  _resetTyping,
} from "../lib/chat-typing.ts";

// ---------------------------------------------------------------------------
// Expiry predicate — the whole "typing" indicator can only be as trustworthy as
// this. A stuck flag showing "typing…" forever is exactly what it must prevent.
// ---------------------------------------------------------------------------

test("isTypingActive: a fresh stamp is active", () => {
  const now = 1_000_000;
  assert.equal(isTypingActive(now, now), true);
});

test("isTypingActive: a stamp within the TTL is active", () => {
  const now = 1_000_000;
  assert.equal(isTypingActive(now - (TYPING_TTL_MS - 1), now), true);
});

test("isTypingActive: a stamp at/after the TTL has expired", () => {
  const now = 1_000_000;
  assert.equal(isTypingActive(now - TYPING_TTL_MS, now), false);
  assert.equal(isTypingActive(now - (TYPING_TTL_MS + 5000), now), false);
});

test("isTypingActive: absent / zero / future timestamps are never active", () => {
  const now = 1_000_000;
  assert.equal(isTypingActive(undefined, now), false);
  assert.equal(isTypingActive(0, now), false);
  assert.equal(isTypingActive(now + 5000, now), false, "a future stamp is not treated as active");
});

// ---------------------------------------------------------------------------
// mark/read round-trip and per-direction isolation.
// ---------------------------------------------------------------------------

test("markTyping is read back per direction and expires on its own", () => {
  _resetTyping();
  const id = randomUUID();
  const t0 = 5_000_000;

  markTyping(id, "visitor", t0);
  assert.deepEqual(readTyping(id, t0), { visitor: true, agent: false });

  // Agent typing is independent of the visitor's stamp.
  markTyping(id, "agent", t0 + 1000);
  assert.deepEqual(readTyping(id, t0 + 1000), { visitor: true, agent: true });

  // After the visitor's stamp ages past the TTL, only the newer agent stamp lives.
  const later = t0 + TYPING_TTL_MS + 1;
  assert.deepEqual(readTyping(id, later), {
    visitor: false,
    agent: isTypingActive(t0 + 1000, later),
  });

  // Well past both stamps, nothing is active.
  const muchLater = t0 + 10 * TYPING_TTL_MS;
  assert.deepEqual(readTyping(id, muchLater), { visitor: false, agent: false });
});

test("readTyping on an unknown conversation is inactive both ways", () => {
  _resetTyping();
  assert.deepEqual(readTyping(randomUUID()), { visitor: false, agent: false });
});

// ---------------------------------------------------------------------------
// SOURCE TRIPWIRES — the signal must actually travel both ends.
// ---------------------------------------------------------------------------

function readSrc(rel: string): string {
  return stripCommentsAndStrings(readFileSync(fileURLToPath(new URL(rel, import.meta.url)), "utf8"));
}

test("the widget sends its own typing signal and displays the agent's", () => {
  const src = readSrc("../components/ChatWidget.tsx");
  assert.match(src, /\/api\/chat\/typing/, "widget POSTs a visitor-typing ping");
  assert.match(src, /setAgentTyping\(/, "widget reflects the agent-typing flag from the poll");
});

test("the GET poll returns the agent-typing flag to the widget", () => {
  const src = readSrc("../app/api/chat/route.ts");
  assert.match(src, /readTyping\(/, "GET /api/chat surfaces the typing state");
});

test("the admin inbox both signals and displays typing", () => {
  const src = readSrc("../components/admin/ChatInbox.tsx");
  assert.match(src, /signalAgentTyping\(/, "admin emits agent-typing while composing");
  assert.match(src, /visitorTyping/, "admin renders the visitor-typing indicator");
});

